"""Shared utilities for taxonomy unification."""
import csv, re, os, json
import numpy as np
from nltk.stem import WordNetLemmatizer

import nltk
for pkg in ['wordnet', 'omw-1.4']:
    try:
        nltk.data.find(f'corpora/{pkg}')
    except LookupError:
        nltk.download(pkg, quiet=True)

_lem = WordNetLemmatizer()
_lemcache = {}

# Tokens that are too generic to be distinctive in a category NAME.
GENERIC = {
    'product', 'products', 'supply', 'supplies', 'accessory', 'accessories',
    'other', 'others', 'general', 'misc', 'miscellaneous', 'item', 'items',
    'equipment', 'gear', 'set', 'sets', 'kit', 'kits', 'part', 'parts',
    'type', 'types', 'good', 'goods', 'and', 'or', 'the', 'for', 'with',
    'accessory', 'tool', 'tools', 'replacement', 'system', 'systems',
    'component', 'components', 'assorted', 'variety', 'collection',
}
STOP = {'and', 'or', 'the', 'for', 'with', 'of', 'a', 'an', 'to', 'in', 'by',
        'n', 'amp'}


def _lemma(w):
    if w in _lemcache:
        return _lemcache[w]
    out = _lem.lemmatize(w)            # noun (plural -> singular)
    _lemcache[w] = out
    return out


def normalize_segment(seg):
    """Return list of normalized tokens for one path segment."""
    s = seg.lower().strip()
    s = s.replace('&', ' and ')
    s = re.sub(r"[''`]", '', s)        # drop apostrophes (women's -> womens)
    s = re.sub(r'[^a-z0-9]+', ' ', s)  # everything else -> space
    toks = []
    for w in s.split():
        if w in STOP:
            continue
        toks.append(_lemma(w))
    return toks


def normalize_path(raw_path):
    """Split a raw 'a > b > c' path into list of (raw_seg, [tokens])."""
    segs = [p.strip() for p in raw_path.split('>')]
    segs = [p for p in segs if p]
    return [(s, normalize_segment(s)) for s in segs]


def load_rows():
    """Load all three sources. Returns list of dicts."""
    files = {
        'amazon': 'amazon_product_categories.csv',
        'facebook': 'fb_product_categories.csv',
        'google': 'google_shopping_product_categories.csv',
    }
    rows = []
    for src, fn in files.items():
        with open(os.path.join('/root/data', fn), newline='', encoding='utf-8-sig') as f:
            r = csv.DictReader(f)
            for rec in r:
                raw = (rec.get('category_path') or '').strip()
                if not raw:
                    continue
                segs = normalize_path(raw)
                if not segs:
                    continue
                rows.append({
                    'source': src,
                    'category_path': raw,
                    'segs_raw': [s for s, _ in segs],
                    'segs_tok': [t for _, t in segs],
                    'depth': len(segs),
                })
    return rows


def embed_text_for_path(segs_tok):
    """Text used for embedding a full path: normalized tokens joined."""
    return ' '.join(' '.join(t for t in seg) for seg in segs_tok).strip()


def build_embeddings(texts, cache_path):
    """Embed unique texts with caching to .npz."""
    uniq = sorted(set(texts))
    if os.path.exists(cache_path):
        d = np.load(cache_path, allow_pickle=True)
        if list(d['keys']) == uniq:
            return {k: v for k, v in zip(d['keys'], d['vecs'])}
    from sentence_transformers import SentenceTransformer
    m = SentenceTransformer('all-MiniLM-L6-v2')
    vecs = m.encode(uniq, batch_size=128, show_progress_bar=True,
                    normalize_embeddings=True)
    np.savez(cache_path, keys=np.array(uniq, dtype=object), vecs=vecs)
    return {k: v for k, v in zip(uniq, vecs)}

