def make_names(child_members, level, ancestor_tokens):
    """Given list-of-(member-index-list) per child cluster, return list of
    names that are distinctive across siblings and avoid ancestor words."""
    S = len(child_members)
    # token frequency per cluster (document = cluster; count members containing token)
    tf = []          # list of Counter: token -> fraction of members containing it
    for mem in child_members:
        c = Counter()
        for i in mem:
            for t in set(seg_tokens(i, level)):
                c[t] += 1
        n = max(1, len(mem))
        tf.append({t: v / n for t, v in c.items()})
    # document frequency across siblings (token "prominent" in a cluster if tf>0.15)
    df = Counter()
    for d in tf:
        for t, f in d.items():
            if f > 0.15:
                df[t] += 1

    def score(t, f):
        return f * math.log((1 + S) / (1 + df[t]))

    # ranked distinctive token list per cluster
    ranked = []
    for ci, d in enumerate(tf):
        cand = []
        for t, f in d.items():
            if t in STOP or t in ancestor_tokens or len(t) < 2:
                continue
            cand.append((t, f, score(t, f), t in GENERIC))
        cand.sort(key=lambda x: (x[3], -x[2], -x[1]))  # non-generic, high score/freq
        toks = [t for t, _, _, _ in cand]
        if not toks:  # fallback: frequent token regardless of generic/ancestor
            allc = Counter()
            for i in child_members[ci]:
                for t in set(seg_tokens(i, level)):
                    if t not in STOP and len(t) >= 2:
                        allc[t] += 1
            toks = [t for t, _ in allc.most_common(3)] or ['group']
        ranked.append(toks)

    # greedy unique naming: grow each name with extra distinctive tokens until
    # unique among siblings; numeric suffix as last resort (always terminates).
    names, reps = [], []
    used = set()
    for ci, toks in enumerate(ranked):
        name = None
        for nwords in (1, 2, 3):
            cand_name = ' | '.join(title(t) for t in toks[:nwords])
            if cand_name not in used:
                name = cand_name
                break
        if name is None:
            base = ' | '.join(title(t) for t in toks[:3]) or title(toks[0])
            j = 2
            name = f'{base} {j}'
            while name in used:
                j += 1
                name = f'{base} {j}'
        used.add(name)
        names.append(name)
        reps.append(tf[ci].get(toks[0], 0.0))  # coverage of primary token
    return names, reps


