def make_names(child_members, level, ancestor_tokens):
    """Name sibling clusters so that (a) no word is shared with an ancestor,
    and (b) no word is shared between any two siblings -> pairwise word
    overlap is 0%. Vocabulary is drawn from THIS level plus the next, so a
    redundant repeated segment (e.g. 'clothing > clothing') doesn't collapse
    all siblings onto one token -- the distinguishing sub-theme surfaces."""
    S = len(child_members)

    def bag(i, deep=False):
        lvls = range(level, (6 if deep else level + 2))
        toks = []
        for lv in lvls:
            toks += seg_tokens(i, lv)
        return toks

    # tf[ci][token] = fraction of members whose (level, level+1) bag has token
    tf = []
    for mem in child_members:
        c = Counter()
        for i in mem:
            for t in set(bag(i)):
                c[t] += 1
        n = max(1, len(mem))
        tf.append({t: v / n for t, v in c.items()})
    df = Counter()
    for d in tf:
        for t, f in d.items():
            if f > 0.10:
                df[t] += 1

    def score(t, f):
        return f * math.log((1 + S) / (1 + df[t]))

    # ranked candidate (token, freq, score) per cluster, ancestor/stop removed
    ranked = []
    for ci, d in enumerate(tf):
        cand = [(t, f, score(t, f), t in GENERIC) for t, f in d.items()
                if t not in STOP and t not in ancestor_tokens and len(t) >= 2]
        cand.sort(key=lambda x: (x[3], -x[2], -x[1]))  # non-generic, strong first
        ranked.append(cand)

    # ---- greedily assign globally-unique words across siblings ----
    claimed = set()
    primary = [None] * S
    # strong clusters claim their best token first
    order = sorted(range(S),
                   key=lambda ci: -(ranked[ci][0][2] if ranked[ci] else -1.0))
    for ci in order:
        for t, f, sc, gen in ranked[ci]:
            if t not in claimed:
                primary[ci] = t
                claimed.add(t)
                break
    # deep fallback for clusters that found no free token at this level
    for ci in order:
        if primary[ci] is not None:
            continue
        allc = Counter()
        for i in child_members[ci]:
            for t in set(bag(i, deep=True)):
                if (t not in STOP and t not in ancestor_tokens
                        and t not in claimed and len(t) >= 2):
                    allc[t] += 1
        if allc:
            t = allc.most_common(1)[0][0]
            primary[ci] = t
            claimed.add(t)

    # build names: primary + one extra unique word for richness when available
    names, reps = [], []
    for ci in range(S):
        toks = []
        if primary[ci]:
            toks.append(primary[ci])
            for t, f, sc, gen in ranked[ci]:
                if t != primary[ci] and t not in claimed:
                    toks.append(t)
                    claimed.add(t)
                    break
        if not toks:
            # last resort: indexed label (kept unique, shares no '|'-word)
            toks = [f'group {ci + 1}']
        name = ' | '.join(title(t) for t in toks[:5])
        names.append(name)
        reps.append(tf[ci].get(primary[ci], 0.0) if primary[ci] else 0.0)
    return names, reps

